\begin{ex}%[6H8N3]
\immini[thm]{
Em hãy kể tên các đoạn thẳng có đầu mút là hai trong ba điểm ${H}$, ${L}$, ${Q}$, ${T}$.

\choice
{ ${HL}$, ${LQ}$ }
   {  ${HQ}$ }
     { \True ${HL}$, ${HQ}$, ${HT}$, ${LQ}$, ${LT}$ và ${QT}$ }
    { ${HL}$, ${HQ}$, ${HT}$, ${LQ}$ }
}{
\begin{tikzpicture}[>=stealth,line join=round,line cap=round,font=\footnotesize,scale=1]
    \path
    (0,0) coordinate (A)
    (2,-0.5) coordinate (B)
    (4,0) coordinate (C)
    (1,-1.5) coordinate (D)
    ;
    \filldraw[black] (A) circle (1pt) node[above right] {$H$};
        \filldraw[black] (B) circle (1pt) node[above left] {$L$};
    \filldraw[black] (C) circle (1pt) node[above right] {$Q$};
        \filldraw[black] (D) circle (1pt) node[above left] {$T$};

    \end{tikzpicture}
}
\loigiai{
Cứ hai điểm phân biệt trong $4$ điểm tạo thành một đoạn thẳng, nên số đoạn thẳng là $\dfrac{4 \cdot (4-1)}{2} = 6$. Các đoạn thẳng đó là: $HL$, $HQ$, $HT$, $LQ$, $LT$, $QT$.
}\end{ex}

