\choice
{ ${CI}$, ${CM}$, ${CW}$, ${IM}$, ${IW}$ }
   { ${CI}$, ${IM}$ }
     { \True ${CI}$, ${CM}$, ${CW}$, ${IM}$, ${IW}$ và ${MW}$ }
    {  ${CM}$ }
}{
\begin{tikzpicture}[>=stealth,line join=round,line cap=round,font=\footnotesize,scale=1]
    \path
    (0,0) coordinate (A)
    (2,-0.5) coordinate (B)
    (4,0) coordinate (C)
    (1,-1.5) coordinate (D)
    ;
    \filldraw[black] (A) circle (1pt) node[above right] {$C$};
        \filldraw[black] (B) circle (1pt) node[above left] {$I$};
    \filldraw[black] (C) circle (1pt) node[above right] {$M$};
        \filldraw[black] (D) circle (1pt) node[above left] {$W$};

    \end{tikzpicture}
}
\loigiai{
Cứ hai điểm phân biệt trong $4$ điểm tạo thành một đoạn thẳng, nên số đoạn thẳng là $\dfrac{4 \cdot (4-1)}{2} = 6$. Các đoạn thẳng đó là: $CI$, $CM$, $CW$, $IM$, $IW$, $MW$.
}\end{ex}

